cd /tmp && peak() { "$@" >/dev/null & p=$!; m=0; while kill -0 $p 2>/dev/null; do v=$(grep VmHWM /proc/$p/status 2>/dev/null | tr -dc '0-9'); [ -n "$v" ] && [ "$v" -gt "$m" ] && m=$v; sleep 0.02; done; wait $p; echo "peakRSS=${m}kB rc=$?"; }
echo -n "cpp  n=8000000 "; peak /workspace/dataset/test6_executable 8000000
echo -n "rust n=8000000 "; peak /output/test6 8000000
